import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 42

    try:
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), strict=False))
    except csv.Error:
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), strict=False))

    if not records:
        return {"columns": [], "rows": []}

    def clean(value):
        value = value.lstrip("\ufeff")
        return re.sub(r"\s+", " ", value).strip()

    def is_numeric(value):
        value = clean(value)
        if not value:
            return False
        return bool(
            re.fullmatch(
                r"[\s£$€()\-+,\d.%/]+",
                value,
            )
        )

    header_index = None
    minimum_width = max(3, expected_width // 2)

    for index, record in enumerate(records):
        nonempty = [clean(value) for value in record if clean(value)]
        if (
            len(record) >= minimum_width
            and record
            and clean(record[0])
            and len(nonempty) >= 3
            and sum(not is_numeric(value) for value in nonempty) >= 2
        ):
            header_index = index
            break

    if header_index is None:
        header_index = next(
            (i for i, record in enumerate(records) if any(clean(v) for v in record)),
            0,
        )

    header_records = [records[header_index]]
    data_start = header_index + 1

    while data_start < len(records):
        record = records[data_start]
        nonempty = [clean(value) for value in record if clean(value)]

        if not nonempty:
            header_records.append(record)
            data_start += 1
            continue

        leading = [clean(value) for value in record[:3]]
        continuation = (
            not any(leading)
            and any(not is_numeric(value) for value in nonempty)
        )
        if not continuation:
            break

        header_records.append(record)
        data_start += 1

    width = max(
        expected_width,
        max((len(record) for record in header_records), default=0),
        max((len(record) for record in records[data_start:]), default=0),
    )

    columns = []
    for column_index in range(width):
        parts = []
        for record in header_records:
            if column_index < len(record):
                value = clean(record[column_index])
                if value and value not in parts:
                    parts.append(value)
        columns.append(" / ".join(parts) if parts else f"Column {column_index + 1}")

    rows = []
    for record in records[data_start:]:
        row = [clean(value) for value in record]
        if len(row) < width:
            row.extend([""] * (width - len(row)))
        rows.append(row)

    return {"columns": columns, "rows": rows}
